#!/usr/bin/env python3
"""Temporary, checksum-guarded installer for the locally verified TEST71-only fix.
The final cleanup commit removes this installer and its publishing workflow.
No database, environment secrets, other branches, or existing user work are touched.
"""
import base64, gzip, hashlib, json, os, pathlib, subprocess
ROOT = pathlib.Path(__file__).resolve().parents[1]
os.chdir(ROOT)
assert os.environ.get('GITHUB_REF') == 'refs/heads/test71-real-chat-e2e-finalization', 'TEST71 only'
PAYLOAD = ''''''
raw = gzip.decompress(base64.b64decode(PAYLOAD))
assert hashlib.sha256(raw).hexdigest() == 'c016537f62d60cd65f26e76c126e20ace3ecac700ebf1d8b33367b9dd9a83590', 'Payload checksum mismatch'
bundle = json.loads(raw)
assert subprocess.check_output(['git','rev-parse','HEAD^'], text=True).strip() == bundle['base'], 'Unexpected base; do not overwrite concurrent work'
values = {}
for name, expected in bundle['before'].items():
    p = ROOT / name
    assert not pathlib.Path(name).is_absolute() and '..' not in pathlib.Path(name).parts
    data = p.read_bytes() if p.exists() else None
    actual = hashlib.sha256(data).hexdigest() if data is not None else None
    assert actual == expected, 'Source changed: ' + name
    values[name] = data.decode('utf-8') if data is not None else None
for name, old, new in bundle['edits']:
    assert values[name].count(old) == 1, 'Ambiguous edit: ' + name
    values[name] = values[name].replace(old, new)
values.update(bundle['files'])
for name, value in values.items():
    assert hashlib.sha256(value.encode()).hexdigest() == bundle['after'][name], 'Result differs from verified source: ' + name
for name, value in values.items():
    p = ROOT / name
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(value, encoding='utf-8')
(pathlib.Path(os.environ['RUNNER_TEMP']) / 'test71-paths.txt').write_text('\n'.join(sorted(values)) + '\n')
print('Applied exactly', len(values), 'checksum-verified TEST71 files; no backend mutations.')
